using System;using System.Linq;using Mono.Cecil;using Mono.Cecil.Cil;using System.Collections.Generic;
class VerifyFill{static IEnumerable<TypeDefinition> Types(TypeDefinition t){yield return t;foreach(var n in t.NestedTypes)foreach(var v in Types(n))yield return v;}static string Body(MethodDefinition m){if(!m.HasBody)return "";return String.Join("|",m.Body.Variables.Select(v=>v.VariableType.FullName).ToArray())+"\n"+String.Join("\n",m.Body.Instructions.Select(i=>i.OpCode.Name+":"+(i.Operand is Instruction?m.Body.Instructions.IndexOf((Instruction)i.Operand).ToString():i.Operand is Instruction[]?String.Join(",",((Instruction[])i.Operand).Select(x=>m.Body.Instructions.IndexOf(x).ToString()).ToArray()):Convert.ToString(i.Operand))).ToArray());}static void Main(string[]a){var x=AssemblyDefinition.ReadAssembly(a[0]);var y=AssemblyDefinition.ReadAssembly(a[1]);var before=x.MainModule.Types.SelectMany(Types).SelectMany(t=>t.Methods).ToArray();var after=y.MainModule.Types.SelectMany(Types).SelectMany(t=>t.Methods).ToArray();if(before.Length!=after.Length)throw new Exception("Method count");var changed=new List<string>();for(int i=0;i<before.Length;i++){if(before[i].MetadataToken!=after[i].MetadataToken)throw new Exception("Token changed");if(Body(before[i])!=Body(after[i])||before[i].FullName!=after[i].FullName)changed.Add(before[i].DeclaringType.FullName+"."+before[i].Name);}if(String.Join(",",changed.OrderBy(s=>s).ToArray())!="UIPanel.Fill,UIPanel.LateUpdate")throw new Exception("Unexpected modifications: "+String.Join(",",changed.ToArray()));if(String.Join(",",x.MainModule.AssemblyReferences.Select(z=>z.FullName).ToArray())!=String.Join(",",y.MainModule.AssemblyReferences.Select(z=>z.FullName).ToArray()))throw new Exception("Assembly dependencies changed");Console.WriteLine("Verified "+before.Length+" methods: exactly private UIPanel.Fill + LateUpdate changed; assembly dependencies identical");}}
